# Let me find connected components for each color (using BFS/flood fill)
from collections import deque

def get_connected_components(grid, target_color):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == target_color and (i, j) not in visited:
                # Start BFS
                component = []
                queue = deque([(i, j)])
                visited.add((i, j))
                while queue:
                    r, c = queue.popleft()
                    component.append((r, c))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == target_color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                components.append(component)
    return components

print("Connected components for each color:")
for color in [1, 2, 8]:
    comps = get_connected_components(grid, color)
    print(f"Color {color}: {len(comps)} components")
    for i, comp in enumerate(comps):
        print(f"  Component {i}: {sorted(comp)}")

